import {removeWorldItem} from './deletion.js';
import {richText,textValue} from './formatting.js';
import {uid,escapeHTML as e} from './store.js';
import {documentTargets,resolveTarget} from './document-links.js';
export const dateKey=date=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
export function validDate(key){if(!/^\d{4}-\d{2}-\d{2}$/.test(key||''))return false;const [y,m,d]=key.split('-').map(Number),date=new Date(y,m-1,d);return y>=1900&&y<=9999&&dateKey(date)===key;}
export function monthCells(year,month){const first=new Date(year,month,1),offset=(first.getDay()+6)%7;return Array.from({length:42},(_,i)=>dateKey(new Date(year,month,1-offset+i)));}
const positions=new Map();
export function mountCalendar(main,w,{modal,field,save,navigate,confirmDelete,heading,btn}){
  const today=dateKey(new Date()),initial=positions.get(w.id)||{month:today.slice(0,7),day:today};let {month,day}=initial;
  const abort=new AbortController();const readable=key=>new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(key+'T12:00:00'));
  const sorted=()=>w.calendarEvents.filter(ev=>ev.date===day).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));
  function render(){positions.set(w.id,{month,day});const [year,m]=month.split('-').map(Number);main.innerHTML=`<div class="page calendar-page">${heading('UM TEMPO PARA CADA HISTÓRIA','Calendário','Planeje sua escrita e conecte acontecimentos às suas páginas.',btn('＋ Novo evento','calendarEvent'))}<div class="calendar-toolbar"><div class="month-controls"><button class="icon-button" data-calendar-month="-1" aria-label="Mês anterior">‹</button><h2>${e(new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(new Date(year,m-1,1)))}</h2><button class="icon-button" data-calendar-month="1" aria-label="Próximo mês">›</button></div><div class="toolbar"><input type="month" id="calendarMonth" aria-label="Ir para mês" value="${month}" min="1900-01" max="9999-12"><button class="button ghost" id="calendarToday">Hoje</button></div></div><div class="calendar-layout"><section class="calendar-grid" aria-label="Dias do mês"><div class="calendar-weekdays">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(label=>`<span>${label}</span>`).join('')}</div><div class="calendar-days">${monthCells(year,m-1).map(key=>{const events=w.calendarEvents.filter(ev=>ev.date===key);return `<button class="calendar-day ${key.slice(0,7)!==month?'outside-month':''} ${key===today?'is-today':''} ${key===day?'is-selected':''}" data-calendar-day="${key}" aria-label="${readable(key)}; ${events.length} eventos" aria-pressed="${key===day}"><span class="day-number">${Number(key.slice(-2))}</span><div class="day-events">${events.slice(0,2).map(ev=>`<span>${e(ev.title)}</span>`).join('')}${events.length>2?`<small>+${events.length-2}</small>`:''}</div></button>`;}).join('')}</div></section><aside class="day-agenda"><span class="eyebrow">SUA AGENDA</span><h2>${readable(day)}</h2><button class="button ghost" id="newDayEvent">＋ Adicionar neste dia</button><div class="agenda-items">${sorted().map(ev=>{const target=resolveTarget(w,ev.target);return `<article class="agenda-event"><button data-edit-event="${ev.id}"><small>${ev.time||'Dia inteiro'}</small><h3>${e(ev.title)}</h3><div class="rich-prose">${richText(ev.description)}</div></button>${target?`<button class="event-link" data-open-event-link="${ev.id}">↗ ${e(target.emoji||'')} ${e(target.title)}</button>`:ev.target?'<small class="help">A página vinculada foi removida.</small>':''}</article>`;}).join('')||'<div class="empty"><p>Um dia com espaço para imaginar.</p><small>Adicione uma sessão de escrita, um prazo ou uma ideia.</small></div>'}</div></aside></div></div>`;
    main.querySelector('#calendarMonth').onchange=event=>{if(/^\d{4}-\d{2}$/.test(event.target.value)){month=event.target.value;day=month+'-01';render();}};
  }
  function editEvent(id){const event=w.calendarEvents.find(ev=>ev.id===id);modal(event?'Editar evento':'Um tempo para escrever',field('Título','title',event?.title||'','text',true)+`<div class="field-grid">${field('Data','date',event?.date||day,'date',true)}${field('Horário (opcional)','time',event?.time||'','time')}</div>`+field('Descrição','description',event?.description||'','textarea')+`<label class="field"><span>Vincular uma pasta ou documento</span><select name="target"><option value="">Sem vínculo</option><optgroup label="Pastas">${w.folders.map(f=>`<option value="${f.id}" ${event?.target===f.id?'selected':''}>▱ ${e(f.name)}</option>`).join('')}</optgroup><optgroup label="Documentos e notas">${documentTargets(w).map(n=>`<option value="${n.id}" ${event?.target===n.id?'selected':''}>${e(n.emoji)} ${e(n.title)} · ${e(n.label)}</option>`).join('')}</optgroup></select></label>${event?'<button type="button" id="deleteCalendarEvent" class="text-link">Excluir evento</button>':''}`,data=>{if(!validDate(data.get('date')))throw Error('Escolha uma data válida entre os anos 1900 e 9999.');const value={id:event?.id||uid(),title:String(data.get('title')).trim()||'Novo evento',date:data.get('date'),time:data.get('time'),description:data.get('description'),target:data.get('target')};if(event)Object.assign(event,value);else w.calendarEvents.push(value);day=value.date;month=day.slice(0,7);save();render();});if(event)document.querySelector('#deleteCalendarEvent').onclick=()=>{document.querySelector('#modal').close();confirmDelete('Excluir evento?','O evento será removido. As páginas vinculadas serão preservadas.',()=>removeWorldItem(w,'calendarEvents',event.id));};}
  main.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.calendarMonth){const [y,m]=month.split('-').map(Number),date=new Date(y,m-1+Number(button.dataset.calendarMonth),1);if(date.getFullYear()<1900||date.getFullYear()>9999)return;month=dateKey(date).slice(0,7);render();}else if(button.dataset.calendarDay){day=button.dataset.calendarDay;render();}else if(button.id==='calendarToday'){month=today.slice(0,7);day=today;render();}else if(button.dataset.editEvent)editEvent(button.dataset.editEvent);else if(button.dataset.openEventLink){const ev=w.calendarEvents.find(ev=>ev.id===button.dataset.openEventLink),target=resolveTarget(w,ev?.target);if(target)navigate(target);}else if(button.id==='newDayEvent'||button.dataset.action==='calendarEvent')editEvent();},{signal:abort.signal});
  render();return()=>abort.abort();
}
